#include <bits/stdc++.h>
using namespace std;

class Fibonacci {
private:
    long long mod;
    map<long long, long long> calculatedNumbers;
public:
    Fibonacci(long long mod) {
        calculatedNumbers[0LL] = 1LL;
        calculatedNumbers[1LL] = 1LL;
        this->mod = mod;
    }

    long long fib(long long n) {
        map<long long, long long>::iterator it = calculatedNumbers.find(n);
        if (it != calculatedNumbers.end()) return it->second;

        long long k = n / 2, res;
        if (n % 2 == 0) {
            res = (fib(k) * fib(k) + fib(k - 1) * fib(k - 1)) % mod;
        } else {
            res = (fib(k) * fib(k + 1) + fib(k - 1) * fib(k)) % mod;
        }
        calculatedNumbers[n] = res;
        return res;
    }
};

class Exponentation {
public:
    // a^b mod m
    static long long calc(long long a, long long b, long long m) {
        if (b == 0) return 1;
        if (b == 1) return a;
        if (b % 2 == 0) return calc(a * a % m, b / 2, m);
        else return a * calc((a * a % m), (b - 1) / 2, m) % m;
    }
};

