    void read(InputReader &in) {
        n = in.nextLong();
        k = in.nextLong();
        l = in.nextLong();
        MOD = in.nextLong();
    }

    void solve(InputReader &in, ostream &out) {
        read(in);
        if (l != 64 && (1LL << l) - 1 < k) {
            out << 0 << "\n";
            return;
        }

        Fibonacci f(MOD);
        long long zeroPos = f.fib(n + 1);
        long long onePos = Exponentation::calc(2, n, MOD) - zeroPos;
        while (onePos < 0) onePos += MOD;

        long long res = 1;
        for (int i = 0; i < l; i++) {
            if ((k & (1LL << i)) != 0) res *= onePos;
            else res *= zeroPos;
            res %= MOD;
        }
        out << res % MOD << "\n";
    }
};

